def slug(p): return f'project-{p["id"]}.html'

def header(active):
    return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="nav-wrap"><a class="brand" href="index.html" aria-label="Gabriele Ciccolella home"><span class="monogram">gc<span>.</span></span><span class="brand-name">Gabriele Ciccolella</span></a><nav aria-label="Main navigation"><a href="projects.html" {'aria-current="page"' if active=='projects' else ''}>Projects</a><a href="index.html#about">About</a><a href="contact.html" {'aria-current="page"' if active=='contact' else ''}>Contact</a><a class="nav-cv" href="{CV}" target="_blank" rel="noopener">CV {EXTERNAL}</a></nav></div><div class="reading-progress" aria-hidden="true"></div></header>'''

def footer():
    return f'''<footer class="site-footer"><div class="container footer-grid"><div><a class="brand footer-brand" href="index.html">gc<span>.</span></a><p>AI, machine learning and the engineering<br>that brings them together.</p></div><div class="footer-links"><a href="mailto:{EMAIL}">Email {EXTERNAL}</a><a href="{LINKEDIN}" target="_blank" rel="noopener noreferrer">LinkedIn {EXTERNAL}</a><a href="{GITHUB}" target="_blank" rel="noopener noreferrer">GitHub {EXTERNAL}</a></div><div class="footer-note"><span>Based in Rome, Italy</span><span>&copy; 2026 Gabriele Ciccolella</span></div></div></footer><button class="back-top" type="button" aria-label="Back to top">&uarr;</button>'''

def page(filename,title,description,content,active='',body_class=''):
    canonical='https://gabrieleciccolella.github.io/'+filename
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f4f5ef"><title>{escape(title)} | Gabriele Ciccolella</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title,quote=True)} | Gabriele Ciccolella"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://gabrieleciccolella.github.io/assets/img/gabriele-ciccolella.jpeg"><meta name="twitter:card" content="summary"><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"><link rel="preload" href="assets/fonts/space-grotesk.woff2" as="font" type="font/woff2" crossorigin><link rel="preload" href="assets/fonts/dm-sans.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="style.css"><script src="app.js" defer></script></head><body class="{body_class}">{header(active)}{content}{footer()}</body></html>'''
    (ROOT/filename).write_text(html,encoding='utf-8',newline='\n')

def card(p,featured=False):
    media=f'<img src="{p["image"]}" alt="" loading="lazy" width="720" height="430">' if p.get('image') else art(p['category'])
    return f'''<article class="project-card {'featured-card' if featured else ''} {p['category']}-card reveal"><a class="project-visual" href="{slug(p)}" aria-label="Explore {escape(p['title'],quote=True)}">{media}<span class="visual-corner">{EXTERNAL}</span></a><div class="project-info"><p class="eyebrow">{p['topic']}</p><h3><a href="{slug(p)}">{p['title']}</a></h3><p>{p['brief']}</p>{tags(p['tools'])}{link(slug(p),'Explore project')}</div></article>'''

