def projects():
    groups=[('ml','ML projects','Learning from data.','Classification, model comparison and validation across three application areas.'),('dl','DL projects','Learning over time.','Sequence modelling for photovoltaic power forecasting with weather covariates.'),('qkd','QKD software emulator','Engineering quantum security.',"My master's thesis: an observable BB84 simulation, from channel events to final key availability."),('software','Software & AI systems','Making the pieces work together.','Agents, service integration, real-time applications and software testing.')]
    sections=[]
    for i,(key,label,title,intro) in enumerate(groups):
        selected=[p for p in PROJECTS if p['category']==key]
        sections.append(f'<section class="project-group section" id="{key}-projects" data-category="{key}"><div class="group-heading reveal"><p class="eyebrow">0{i+1} / {label}</p><h2>{title}</h2><p>{intro}</p></div><div class="project-grid {"single-project" if len(selected)==1 else ""}">{"".join(card(p) for p in selected)}</div></section>')
    html=f'''<main id="main" class="container"><section class="page-intro"><p class="eyebrow reveal">The project collection</p><h1 class="reveal">Built to <span class="serif-word">understand.</span><br>Built to work.</h1><p class="intro-text reveal">A closer look at my work in machine learning, deep learning, quantum security and software systems.</p></section><div class="project-filters" role="group" aria-label="Filter projects"><button type="button" data-filter="all" aria-pressed="true">All work <span>07</span></button><button type="button" data-filter="ml" aria-pressed="false">ML projects</button><button type="button" data-filter="dl" aria-pressed="false">DL projects</button><button type="button" data-filter="qkd" aria-pressed="false">QKD emulator</button><button type="button" data-filter="software" aria-pressed="false">Software &amp; AI</button></div><p class="filter-status sr-only" aria-live="polite">Showing all 7 projects.</p>{''.join(sections)}<div class="section-bottom">{link('contact.html','Talk about a project','button button-dark')}</div></main>'''
    page('projects.html','Projects','Explore ML projects, weather-aware PV deep learning, the BB84 QKD software emulator and AI systems by Gabriele Ciccolella.',html,active='projects')

def details(p):
    media=art(p['category']) if not p.get('image') else f'<img class="case-cover" src="{p["image"]}" alt="{escape(p["title"],quote=True)}" width="1400" height="600">'
    actions=link(p['source'],'View source code','button button-dark',external=True) if p.get('source') else ''
    if p['id']=='qkd': actions+=link(THESIS,'Read the thesis','button button-dark',external=True)
    if p.get('demo'): actions+=link(p['demo'],'Open live demo','button button-dark',external=True)
    special=''
    if p['id']=='forecasting':
        special='''<section class="case-section reveal"><p class="eyebrow">At a glance</p><div class="facts-grid"><div><strong>72h</strong><span>Historical input</span></div><div><strong>24h</strong><span>Forecast horizon</span></div><div><strong>LSTM</strong><span>Encoder + decoder</span></div><div><strong>lag24</strong><span>Seasonal baseline</span></div></div><p class="small-note">The diagram illustrates the modelling approach, not measured predictions. The default decoder uses observed future weather under a perfect-forecast assumption. Numerical performance is not claimed without a recorded run.</p></section>'''
    if p['id']=='qkd':
        special=f'''<section class="case-section reveal"><p class="eyebrow">Architecture</p><h2>Eight services. One observable workflow.</h2><p>Alice and Bob interact through simulated quantum and classical channels. Eve models intercept-resend; the dashboard coordinates the session and its post-processing. Separate KMS services record the two endpoints' outcomes.</p><figure class="architecture-figure"><a href="assets/img/qkd-architecture.png" target="_blank" rel="noopener"><img src="assets/img/qkd-architecture.png" alt="Architecture from the thesis: dashboard, Alice, Bob, Eve, quantum and classical channels, and two KMS services" width="1448" height="1090" loading="lazy"></a><figcaption>Original architecture figure from the thesis. Select the image to open it at full size.</figcaption></figure><div class="case-callout"><h3>Sicurezza quantistica applicata</h3><p>Studio sperimentale di un'infrastruttura QKD<br>Master's thesis, Universit&agrave; Campus Bio-Medico di Roma, 2026.</p>{link(THESIS,'Download thesis PDF','text-link',download=True)}</div><p class="small-note">For access to the software source repository, please <a href="mailto:{EMAIL}?subject=BB84%20source%20code%20request">contact me</a>.</p></section>'''
    if p['id']=='rehab':
        scores=[('Random Forest',97.30),('Logistic Regression',96.96),('LDA',93.02),('SVM',91.76),('KNN',89.62),('Decision Tree',89.07),('Gaussian Naive Bayes',84.94),('AdaBoost',68.29)]
        bars=''.join(f'<div class="result-bar"><span>{name}</span><div class="bar-track"><i style="--value:{value}%"></i></div><strong>{value:.2f}%</strong></div>' for name,value in scores)
        special=f'<section class="case-section reveal"><p class="eyebrow">Reported project results</p><h2>A comparison across eight classifiers.</h2><div class="results-bars">{bars}</div><p class="small-note">Accuracy values retained from the original project portfolio. They refer to that academic evaluation, rather than a new benchmark or a clinical deployment.</p></section>'
    methods=''.join(f'<div class="method-step"><span class="mono">0{i+1}</span><div><h3>{title}</h3><p>{description}</p></div></div>' for i,(title,description) in enumerate(p['steps']))
    html=f'''<main id="main"><section class="case-intro container"><a class="back-link" href="projects.html">&larr; All projects</a><p class="eyebrow reveal">{p['topic']}</p><h1 class="reveal">{p['title']}</h1><p class="case-subtitle reveal">{p['subtitle']}</p>{tags(p['tools'])}<div class="button-row reveal">{actions}</div></section><div class="container case-media reveal {p['category']}-media">{media}</div><div class="container case-layout"><aside class="case-aside"><p class="eyebrow">Project focus</p><p>{p['topic']}</p><a href="contact.html">Discuss this project {EXTERNAL}</a></aside><div class="case-body"><section class="case-section reveal"><p class="eyebrow">The idea</p><h2>{p['subtitle']}</h2><p>{p['overview']}</p></section><section class="case-section reveal"><p class="eyebrow">The approach</p><div class="method-steps">{methods}</div></section>{special}<section class="case-section reveal"><p class="eyebrow">What I took from it</p><h2>From implementation<br>to understanding.</h2><p>{p['takeaway']}</p></section><div class="case-next">{link('projects.html','Explore more projects','button button-outline')}</div></div></div></main>'''
